<?php
namespace App\Http\Controllers\API;
use App\Http\Controllers\Controller; use App\Http\Resources\AttendanceResource; use App\Models\Attendance; use Illuminate\Http\Request; use Illuminate\Http\JsonResponse; use Illuminate\Validation\Rule;
class AttendanceController extends Controller { public function index(Request $r) { $items=Attendance::with('staff')->where('owner_id',$r->user()->id)->when($r->month,fn($q,$m)=>$q->whereRaw("strftime('%Y-%m', work_date) = ?",[$m]))->latest('work_date')->paginate(20); return AttendanceResource::collection($items)->response(); } public function clockIn(Request $r): JsonResponse { $d=$r->validate(['staff_id'=>['required','integer','exists:staff,id']]); $s=$r->user()->staff()->findOrFail($d['staff_id']); $item=Attendance::firstOrCreate(['owner_id'=>$r->user()->id,'staff_id'=>$s->id,'work_date'=>now()->toDateString()],['status'=>'present']); $item->update(['check_in'=>$item->check_in ?? now()->format('H:i:s')]); return response()->json(new AttendanceResource($item->load('staff'))); } public function clockOut(Request $r, Attendance $attendance): JsonResponse { abort_unless($attendance->owner_id === $r->user()->id,403); $attendance->update(['check_out'=>now()->format('H:i:s')]); return response()->json(new AttendanceResource($attendance->load('staff'))); } }
